rule windows_lolbas_unexpected_target_path {

  meta:
    author = "notcmmartin@"
    description = "Detects a LOLBAS (Living Off The Land Binary And Script) executing from a non-standard or unexpected file path. This could indicate malicious activity attempting to masquerade as legitimate system processes."
    tactic = "TA0005,TA0003,TA0002" 
    technique = "T1036,T1036.003,T1218" 
    severity = "INFO"
    alerting = "false"
    data_table = "LOLBAS1"

  events:
    $e.metadata.log_type = "WINDOWS_SYSMON"
    $e.metadata.event_type = "PROCESS_LAUNCH"
    $host = $e.principal.hostname

    // Extract the process name (e.g., "cmd.exe") from the full path.
    // Example: C:\Windows\System32\cmd.exe -> cmd.exe
    $process = re.capture($e.target.process.file.full_path,`^.*\\([^$]+)$`)

    // Extract the directory path (e.g., "\Windows\System32\") from the full path.
    // Example: C:\Windows\System32\cmd.exe -> \Windows\System32\
    $path = re.capture($e.target.process.file.full_path,`^.*?(\\.*\\)[^$]+$`)

    // Check if the extracted process name is a known LOLBAS (case-insensitive).
    $process = %LOLBAS1.Filename nocase

    // Check if the extracted path is NOT in the list of expected/legitimate paths for that LOLBAS.
    not $path in %LOLBAS1.Paths nocase

    // Capture the expected paths for outcome enrichment.
    $LOLBAS_path = %LOLBAS1.Paths
    $LOLBAS_technique = %LOLBAS1.MITRE_ATT_CK_technique

  match:
    $host over 1m

  outcome:
    $risk_score = max(
        // T1059 Command and Scripting Interpreter
        if($LOLBAS_technique=/T1059/,20,0) + 
        // T1053 Scheduled Task/Job
        if($LOLBAS_technique=/T1053/,20,0) +
        // T1204 User Execution
        if($LOLBAS_technique=/T1204/,20,0) +    
        // T1055 Process Injection 
        if($LOLBAS_technique=/T1055/,20,0) +            
        // T1106 Native API
        if($LOLBAS_technique=/T1106/,20,0) +            
        // T1003 OS Credential Dumping
        if($LOLBAS_technique=/T1003/,20,0) +            
        // T1555 Credentials from Password Stores
        if($LOLBAS_technique=/T1555/,20,0)        
    )
    $observed_process = array_distinct($process)
    $observed_path = array_distinct($path)
    $expected_path = array_distinct($LOLBAS_path)
    $mapped_tactic = array_distinct($LOLBAS_technique)

  condition:
    $e
}

