    author = "djr"
    description = "Detects a single Okta session ID used from multiple source IP addresses within a 1-hour window, potentially indicating session hijacking. Excludes certain ASNs and known corporate IPs."
    severity = "MEDIUM"
    priority = "MEDIUM"
    mitre_technique_id = "T1078.004" // Valid Accounts: Cloud Accounts
    mitre_tactic_id = "TA0003" // Persistence or TA0001 Initial Access

  events:
    // Match successful Okta Single Sign-On (SSO) events
    $okta_event.metadata.product_name = "Okta"
    $okta_event.security_result.action = "ALLOW" // Equivalent to action=success

    // Filter based on known IPs (Splunk: lookup assets_tracker ... where isnull(known_ip))
    // This checks if at least one of the IPs seen in the session is NOT in the known IP list.
    // Assumes %PCI_Network_Ranges is a reference list containing trusted/asset IPs/ranges.
    not $okta_event.principal.ip in cidr %PCI_Network_Ranges  

    // Filter based on ASN (Splunk: search NOT asn IN ("ADOBE*", "OMNITURE"))
    // Note - out of the box, ASN enrichment is done at ingest time, no lookup tables are required
    // The fields principal.ip_geo_artifact.network.organization_name and principal.ip_geo_artifact.network.asn along with 
    // about a dozen other GEOIP related fields are added to every event at ingest as part of this enrichment
    $okta_event.principal.ip_geo_artifact.network.organization_name != /MyCORP.*/ nocase  // Example regex
    $okta_event.principal.ip_geo_artifact.network.organization_name != "MyPROVIDER" nocase

    // Alternative option for filtering ASNs via a reference list (reusable and cleaner)
    // not $okta_event.principal.ip_geo.asn.organization in %trusted_asns

    // Map variables from the filtered events for use in match and condition
    $okta_event.principal.user.userid = $user
    $okta_event.network.parent_session_id = $session_id
    $okta_event.principal.ip = $ip

  match: 
    $user, $session_id over 30m // aggregate events by user and session ID over a 30 minute window (the match window is variable)

  outcome:
    // This is an optional collection of variables that can be extracted, calculated, or otherwise generated, and added to the alert details
    // $risk_score is a special outcome variable that can be used for multi-event risk based alerting, and impacts entity risk score

    // Assigns calculated Risk Score to alert    
    $risk_score = max(
        35
        // Adjust score +15 if ASN is in risky ASN ref list
        + if( $okta_event.principal.ip_geo_artifact.network.organization_name in %SOC_risky_asn_providers, 15, 0) 
    )
    // Add the count of distinct IPs to the alert details (Splunk: eventstats dc(src_ip) as session_ip_count by authenticationContext.externalSessionId user)
    $ip_count = count_distinct($okta_event.principal.ip) 
    // Add the list of distinct IPs to the alert details
    $ip_list = array_distinct($okta_event.principal.ip) 
    // Add the count of distinct ASNs to the alert details (Splunk: eventstats dc(asn) as session_asn_count count by authenticationContext.externalSessionId user )
    $asn_count = count_distinct($okta_event.principal.ip_geo_artifact.network.asn)
    // Add the list of distinct ASNs to the alert details
    $asn_list = array_distinct($okta_event.principal.ip_geo_artifact.network.asn)
    // Add the list of distinct ASN Organizations to the alert details
    $asn_org_list = array_distinct($okta_event.principal.ip_geo_artifact.network.organization_name)
    // Annotates the alert if one of the ASNs is on the risky ASN list
    $asn_risky = array_distinct(if($okta_event.principal.ip_geo_artifact.network.organization_name in %SOC_risky_asn_providers, "Yes", "No"))

  condition:
    // Core detection logic: More than one distinct source IP address associated with the matched user and session ID
    $okta_event and #ip > 1 // Equivalent to eventstats dc(src_ip) ... where session_ip_count > 1
}

rule login_enumeration_exfiltration {
    meta:
description = "Detects when a user logs in without multifactor authentication (MFA) and then performs enumeration and exfiltration"
        rule_name = "Login Without MFA, Enumeration, Exfiltration"
        severity = "High"

    events:
     // Detection with name "Console Login Without MFA"
        // The affected user is saved as $target_user
        $login_without_mfa.detection.detection.rule_name = /Console Login Without MFA/
        $target_user = $login_without_mfa.detection.detection.outcomes["target_user"]

     // Any detection with a rule name containing 'enumeration'
     // The user performing enumeration is the user that logged in without mfa
        $enumeration.detection.detection.rule_name = /enumeration/ nocase
        $enumeration.detection.detection.outcomes["principal_users"] = $target_user

     // Any detection with the mitre tactic 'TA0010' (Exfiltration)
