     // All 3 must occur for a single user
        $login_without_mfa and $enumeration and $exfiltration
}

rule enriched_malicious_process_with_correlated_network_activity {

  meta:
    author = "@google_secops"
    description = "Alerts when a process launch, flagged as MALICIOUS by VirusTotal file enrichment, occurs on a host and is followed closely by network activity from the same host connecting to an IP address. The rule correlates these events within a 1-hour window and leverages Mandiant threat intelligence context for the IP. A dynamic risk score is calculated based on file characteristics (VT severity, signature status, VT tags), VT observation recency, and the Mandiant risk score associated with the destination IP."
    severity = "MEDIUM"
    priority = "HIGH"

    events:
        // Event variable $e: Represents the initial trigger - a process launch
        $e.metadata.event_type = "PROCESS_LAUNCH"
        // Use VirusTotal Enrichment: Filter for processes where VT verdict is MALICIOUS
        $e.target.process.file.security_result.threat_verdict = "MALICIOUS"
        $e.principal.hostname = $hostname
        $e.target.process.file.sha256 = $sha256

        // Event variable $e1: Represents the subsequent network connection
        $e1.metadata.event_type = "NETWORK_CONNECTION"
        $e1.principal.hostname = $hostname        
        $e1.target.ip = $ip

        // Entity variable $ecg: Represents Global Context information associated with the IP address
        $ecg.graph.metadata.entity_type = "IP_ADDRESS"
        $ecg.graph.metadata.source_type = "GLOBAL_CONTEXT"
        $ecg.graph.entity.ip = $ip

    match:
        // Group all events ($e, $e1) and context ($ecg indirectly via $e1's IP) by the hostname.
        // All required events/context for a single hostname must occur within a 1 hour window.
        $hostname over 1h

    outcome:
        $event_time = max($e.metadata.event_timestamp.seconds)
        // Capture the "first seen" timestamp of the file hash from VirusTotal enrichment
        $first_seen_time = max($e.target.process.file.first_seen_time.seconds)
        // Calculate how many days ago VT first saw this file (0 means seen today/within 24hrs)
        $first_seen_delta = cast.as_int(($event_time - $first_seen_time) / 86400)

        // Capture the Mandiant IOC Risk Score associated with the destination IP address from Global Context
        $ioc_risk_score = max($ecg.graph.metadata.threat.risk_score)

        // Capture timestamps to enforce sequence: process launch must precede network connection
        $process_events = max($e.metadata.event_timestamp.seconds)
        $network_events = min($e1.metadata.event_timestamp.seconds) 

        // --- Dynamic Risk Scoring Logic ---
        $risk_score = max(
            35
            // Adjust score based on VirusTotal severity enrichment for the file hash
            - if($e.target.process.file.security_result.severity = "LOW", 10, 0) 
            + if($e.target.process.file.security_result.severity = "MEDIUM", 0)
            + if($e.target.process.file.security_result.severity = "HIGH", 10, 0)

            // Adjust score based on whether the process file is signed
            - if($e.target.resource.attribute.labels["Signed"] = "true", 10, 0)
            + if($e.target.resource.attribute.labels["Signed"] = "false", 10, 0)

            // Increase score based on presence of specific suspicious tags from VirusTotal enrichment
            + if(any $e.target.process.file.tags = "persistence", 5, 0)
            + if(any $e.target.process.file.tags = "detect-debug-environment", 1, 0)
            + if(any $e.target.process.file.tags = "self-delete", 5, 0)
            + if(any $e.target.process.file.tags = "checks-network-adapters", 2, 0)
            + if(any $e.target.process.file.tags = "checks-disk-space", 2, 0)
            + if(any $e.target.process.file.tags = "checks-cpu-name", 2, 0)
            + if(any $e.target.process.file.tags = "invalid-signature", 1, 0)
            + if(any $e.target.process.file.tags = "malware", 10, 0)
            )

            // Increase score significantly if the file hash is very recent according to VirusTotal
            // Newer malware is generally higher risk
            + if($first_seen_delta <= 1, 45, 0)                                   // <1 day
            + if($first_seen_delta <= 7 and $first_seen_delta > 1, 30, 0)         // <7 day    
            + if($first_seen_delta <= 30.44 and $first_seen_delta > 7, 10, 0)     // <30 day    
            + if($first_seen_delta <= 90 and $first_seen_delta > 30.44, 0, 0)     // <90 day
            + if($first_seen_delta > 90, 10, 0)                                 // >90 day

            // Increase score based on Mandiant Fusion IOC Risk Score for the destination IP
            // Leverages Google's threat intelligence on the IP address contacted
            + if($ioc_risk_score > 0 and $ioc_risk_score <= 59, 10)
            + if($ioc_risk_score > 60 and $ioc_risk_score <= 80, 20)            
            + if($ioc_risk_score > 80, 40)                        

        // --- Additional Context Fields for Alert ---
        // Extract distinct embedded URLs found in the process file by VT enrichment
        $embedded_urls = array_distinct($e.target.process.file.embedded_urls)
        // Extract distinct tags associated with the process file by VT enrichment
        $tags = array_distinct($e.target.process.file.tags)

    condition:
        // All event/entity variables must exist for a match
        $e and $e1 and $ecg and
        // Enforce time sequence: Process Launch ($e) must happen before or at the same time as Network Connection ($e1)
        $process_events <= $network_events
        // Optional, filter by Risk Score
        and $risk_score > 60

}

