rule ueba_first_time_login {
  meta:
    description = "Detects the first time a user logs in."
    rule_name = "First time user login activity." 
    severity = "Low"
    priority = "Low"

  events:
    $e.metadata.event_type = "USER_LOGIN" 
    $e.security_result.action = "ALLOW" or $e.security_result.action = "ALLOW_WITH_MODIFICATION"
    $userid = $e.principal.user.userid

  match:
    $userid over 24h

  outcome:
    // Calculate the earliest (min) first_seen timestamp for successful authentications.
    // Uses the metrics.auth_attempts_success function:
    //   - period:1d (daily) - Groups events into daily buckets.
    //   - window:30d (30 days) - Looks back over the past 30 days.
    //   - metric:first_seen - Uses the 'first_seen' timestamp from the metric.
    //   - agg:min -  Finds the *earliest* first_seen timestamp (minimum value).
    //   - principal.user.userid:$userid - Filters the metric data by the user ID.
    $first_seen_successful_auth = max(
        metrics.auth_attempts_success(
          period:1d, window:30d,
          metric:first_seen, agg:min,
          principal.user.userid:$userid
        )
      )
    $risk_score = max(40)

  condition:
    // A detection occurs if:
    // 1. A login event ($e) exists.
    // 2. AND the earliest first_seen timestamp ($first_seen_successful_auth) is 0.
    //    A value of 0 indicates that there were NO previous successful logins
    //    in the 30-day window for this user.
    $e and $first_seen_successful_auth = 0
}

