rule demoverse_Chrome_DLP_HC_Paste_Egress_Following_Upload_Decline {

    //DLP policy warns users when they upload files with sensitive content in Chrome. It does not warn users
    //when they paste sensitive data, but it limits them to ~5 rows of data via a Data Protection Rule in Workspace.
    //This rule tracks those users who decline to upload when warned, but then paste the same data. When they
    //paste the data, this generates a FILE_PASTE event even if it is blocked.  

    //The intent of the rule is to track users who first upload and then paste, but in those cases where content
    //was large and they were blocked, the content hash is unlikely to match because of CRLF differences - opening
    //a file and copying it to the buffer, followed by a paste, will strip out carriage returns (\r) and change the
    //byte count and hash.  This rule takes the original file, calculates 1% of the file size, and then looks to 
    //see if a user later pastes content of less than 1%.


  meta:


    author = "Sam Eagle"
    description = "Detect alternative upload attempts for sensitive data"
    severity = "High"

  events:
    $d1.detection.detection.rule_name = "demoverse_Chrome_Browser_DLP_Warn_Alert"
    //$browser = $d1.detection.collection_elements.references.event.principal.resource.id //Chrome API-managed identifier; using principal email returns zero results, likely because of enrichment
    $file_bytes = $d1.detection.collection_elements.references.event.target.file.size // Using UDM field because Outcome variable is of type string and can't be used in math
    $userid = $d1.detection.detection.outcomes["dlp_user"]  // Original rule uses extracted_fields value therefore no repeated fields
    $target_url = $d1.detection.detection.outcomes["Target_Domains"] 

    ($d2.detection.detection.rule_name = "demoverse_Chrome_DLP_Audit_Low_Volume_Pastes"  or 
    $d2.detection.detection.rule_name = "demoverse_Chrome_DLP_CRX_Activity" )
    // Low Volume Paste Audit Rule or CRX Activity Rule 

    //$browser = $d2.detection.collection_elements.references.event.principal.resource.id
    $paste_bytes = $d2.detection.collection_elements.references.event.target.file.size
    $userid = $d2.detection.detection.outcomes["dlp_user"] 

    $d2.detection.detection_time.seconds > $d1.detection.detection_time.seconds 

  match:
    $userid over 1h

  outcome:

    $risk_score = 80
    $initial_egress = max($file_bytes)
    $lower_bound = sum($file_bytes - ($file_bytes) * .01)
    $hc_target = max($paste_bytes)
    $dlp_user = array_distinct($userid)
    $dlp_url = array_distinct($target_url)

  condition:
    $d1 and $d2  and (($initial_egress >= $hc_target) and ($hc_target >= $lower_bound))
}

rule demoverse_Chrome_DLP_Audit_Low_Volume_Pastes {
    //DLP policy in Workspace lets people paste up to four rows of data without being blocked.
    //Policy further has minimal restrictions on where you can paste this in order not to block
    //the business.  This rule tracks those pastes. A reference list could include a whitelist whereas
    //this rule only excludes dlptest.com and Redmine. 
    //
    //Does not alert. Sets very low risk score. Downstream rule tracking behavior and adjusting
    //risk score as needed.
    //
    //Edited to add: upon further examination this rule tracks all DPR paste events because all
    //pastes have an EVENT_RESULT_DETECTED condition. Those that violate the policy on egress size
    //get blocked by a different rule that results in EVENT_RESULT_BLOCKED. This would be easy to
    //fix were the rule changed to a multi-event rule that tested for the non-existence of 
    //EVENT_RESULT_BLOCKED in a sliding window. For now leaving the lower-impact single-event
    //audit-everything rule in place.

  meta:

    author = "Sam Eagle"
    description = "Track low volume pastes of sensitive data"
    severity = "Low"

  events:
    $dlp.metadata.log_type = "CHROME_MANAGEMENT"
    $dlp.metadata.product_event_type = "sensitiveDataEvent"
    $dlp.additional.fields["transfer_method"] = "FILE_PASTE"
    ($dlp.security_result.rule_name = /Audit low volume sensitive data copies/ or
    $dlp.security_result.action_details != "EVENT_RESULT_BLOCKED" )
    $dlp.target.file.size > 1
    $dlp.target.file.size = $content_size
    //Exclude Chrome Extensions
    $dlp.target.url != /^chrome-extension/
    $dlp.target.url != /dlptest.com/
    $dlp.target.url != "redmine-bce.kushmerek.demo.altostrat.com"
    $dlp.security_result.about.labels.value = $method
    $dlp.target.url = $target_url
    $dlp.extracted.fields["profile_user"] = $userid

  outcome:

    $dlp_user = array_distinct($userid)
    $dlp_url = array_distinct($target_url)
    $dlp_local_user = array_distinct($dlp.target.user.userid)
    $dlp_method = array_distinct($method)
    $dlp_bytes = max($content_size)
    $dlp_day_of_week = timestamp.get_day_of_week($dlp.metadata.event_timestamp.seconds)
    $risk_score = max(5)
    $Target_URLs = array_distinct($dlp.target.url)

  condition:
    $dlp 
}

rule suspicious_auth_unusual_interval_time {

    meta:
        author = "@cmmartin"
        description = "Generates a detection for authentication activity occuring between two locations in an unusual interval of time."
        severity = "LOW"
        priority = "LOW"

    events:
        // filter events
        $e1.metadata.log_type = "WORKSPACE_ACTIVITY"
        $e1.metadata.event_type = "USER_LOGIN"
        $e1.metadata.product_event_type = "login_success"
        $e1.principal.location.region_coordinates.latitude != 0
        $e1.principal.location.region_coordinates.longitude != 0
        // match variables
        $user = $e1.extracted.fields["actor.email"]

        // ensure e1 occurs before e2, and avoid a self join on either event
        $e1.metadata.event_timestamp.seconds < $e2.metadata.event_timestamp.seconds

        // filter events
        $e2.metadata.log_type = "WORKSPACE_ACTIVITY"
        $e2.metadata.event_type = "USER_LOGIN"    
        $e2.metadata.product_event_type = "login_success"
        $e2.principal.location.region_coordinates.latitude != 0
        $e2.principal.location.region_coordinates.longitude != 0       
        // match variables
        $user = $e2.extracted.fields["actor.email"]

    match:
        $user over 1d

    outcome:
        //used to check if filter resouts out if the source and destination are the same 
        $is_same_location = (
            if(
                math.geo_distance(
                    min($e1.principal.location.region_coordinates.longitude),
                    min($e1.principal.location.region_coordinates.latitude),
                    max($e2.principal.location.region_coordinates.longitude),
                    max($e2.principal.location.region_coordinates.latitude)
                ) = 0,
                1, // True, same location
                0  // Fase, not the same location
            )
        )

        // calculate the interval between first and last event, in seconds
        $duration_seconds = max($e2.metadata.event_timestamp.seconds) - min($e1.metadata.event_timestamp.seconds) 

        // calculate the interval between first and last event, in hours
        $duration_hours =  ( 
            ( max($e2.metadata.event_timestamp.seconds) - min($e1.metadata.event_timestamp.seconds) )
            / 3600 
        )

        // calculate the distance using distance between login events, returns result in meters
        $distance_meters = array_distinct(
            math.geo_distance(
                $e1.principal.location.region_coordinates.longitude,
                $e1.principal.location.region_coordinates.latitude,
                $e2.principal.location.region_coordinates.longitude,
                $e2.principal.location.region_coordinates.latitude
            )
        )

        // convert the coordinate results into kilometers
        // - https://cloud.google.com/bigquery/docs/reference/standard-sql/geography_functions#st_distance
        $distance_kilometers = max(
            cast.as_int(
                math.geo_distance(
                    $e1.principal.location.region_coordinates.longitude,
                    $e1.principal.location.region_coordinates.latitude,
                    $e2.principal.location.region_coordinates.longitude,
                    $e2.principal.location.region_coordinates.latitude
                )
            ) 
            / 1000
        )

        // calculate the speed in KPH
        $kph = $distance_kilometers / $duration_hours

        // // generate risk_score based on KPH, i.e., speed over distance travelled
        $risk_score = (
            if($kph > 100, 35) +
            if($kph  > 250, 50) +
            if($kph  > 500, 75) +
            if($kph  > 1000, 90)
        )

        // generates a link to Google Maps
        $google_maps_url = array_distinct(
            strings.concat(
                "https://www.google.com/maps/dir/?api=1&origin=",
                $e1.principal.location.region_coordinates.latitude,
                ",",
                $e1.principal.location.region_coordinates.longitude,
                "&destination=",
                $e2.principal.location.region_coordinates.latitude,
                ",",
                $e2.principal.location.region_coordinates.longitude
            )                                
        )

    condition:
        $e1 and $e2 and $is_same_location = 0 and $risk_score >= 35
}

rule fusion_network_http_url {

    meta:
        author = "cmmartin@"
        description = "Matches Fusion URL IOCs against UDM Network HTTP events."
        priority = "HIGH"
        severity = "MEDIUM"

    events:
        $e.metadata.event_type = "NETWORK_HTTP"
        // match URL with or without protocol
        (
            $e.target.url != "" 
            // exclude the protocol
            and re.regex($e.target.url, `[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)`)
        )

        // Filter graph
        $g.graph.metadata.product_name = "MANDIANT_FUSION_IOC"
        $g.graph.metadata.vendor_name = "MANDIANT_FUSION_IOC"
        $g.graph.metadata.entity_type = "URL"
        $g.graph.metadata.source_type = "GLOBAL_CONTEXT"

        $ioc = $e.target.url
        $ioc = $g.graph.entity.url

    match:
        $ioc over 1h

    outcome:
        // Extract the Mandiant Automated Intel confidence score of maliciousness
        $confidence_score = max(if($g.graph.metadata.threat.verdict_info.source_provider = "Mandiant Automated Intel", $g.graph.metadata.threat.verdict_info.confidence_score, 0))

        // Extract the status of the indicator as seen in a breached environment
        $breached = max(if($g.graph.metadata.threat.verdict_info.pwn = true, 1, 0))

        // Intermediary outcome variable to combine conditions of intelligence extracted in the previous outcome variables.
        // Return 1 if conditions are met, otherwise return 0.
        $matched_conditions = if($confidence_score >= 80 AND $breached = 1, 1, 0)

    condition:
        // Ensure $e1, $context_graph and $matched_conditions conditions are met.
        $e and $g //and $matched_conditions = 1
}
